use vstd::prelude::*;

verus! {

spec fn rotated<T>(s: Seq<T>, n: nat) -> Seq<T>
    recommends n <= s.len(),
{
    s.subrange(n, s.len()) + s.subrange(0, n)
}

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list@ == rotated(list@, n as nat),
        new_list@.len() == list@.len(),
{
    let len = list.len();
    assert!(len > 0, "list must be non-empty");
    assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[n..]);
    new_list.extend_from_slice(&list[..n]);

    // Help the verifier connect the concrete operations to the spec rotation.
    assert(list@.subrange(n as int, len as int) + list@.subrange(0, n as int)
        == rotated(list@, n as nat));

    new_list
}

} // verus!

